<?php use Hls\Http\View as V; ?>
<?php if($access->can('inventory.reservation.create')): ?><section class="panel"><form method="post" class="form-grid"><?= $this->csrf() ?><label>Nomor Reservasi<input name="reservation_ref" required></label><label>Tanggal<input type="date" name="reservation_date" value="<?= date('Y-m-d') ?>" required></label><label>Cabang<select name="branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><label>Gudang<select name="warehouse_id" required><?php foreach($warehouses as $w): if($access->branch((int)$w['branch_id'])): ?><option value="<?= (int)$w['id'] ?>"><?= V::escape($w['code'].' - '.$w['name']) ?></option><?php endif; endforeach ?></select></label><label>Referensi kebutuhan<input name="need_ref"></label><label>Jenis kebutuhan<input name="need_type"></label><label>Keterangan<textarea name="note"></textarea></label><div data-reservation-items><div class="bill-item"><select name="item_id[]" required><option value="">Pilih barang</option><?php foreach($items as $i): ?><option value="<?= (int)$i['id'] ?>"><?= V::escape($i['code'].' - '.$i['name']) ?></option><?php endforeach ?></select><input name="quantity[]" type="number" min="0.001" step="0.001" placeholder="Kuantitas" required><button type="button" data-remove-item>Hapus</button></div></div><button type="button" data-add-item>+ Tambah Barang</button><button class="button button-primary">Simpan Draft</button></form></section><script>document.addEventListener('click',e=>{if(e.target.matches('[data-add-item]')){const box=document.querySelector('[data-reservation-items]'),row=box.querySelector('.bill-item').cloneNode(true);row.querySelectorAll('input').forEach(x=>x.value='');row.querySelectorAll('select').forEach(x=>x.selectedIndex=0);box.appendChild(row)}if(e.target.matches('[data-remove-item]')){const rows=document.querySelectorAll('[data-reservation-items] .bill-item');if(rows.length>1)e.target.closest('.bill-item').remove()}});</script><?php endif ?><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Tanggal</th><th>Cabang/Gudang</th><th>Jenis</th><th>Qty</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['reservation_ref']) ?></td><td><?= V::escape($r['reservation_date']) ?></td><td><?= V::escape($r['branch_code'].' / '.$r['warehouse_code']) ?></td><td><?= (int)$r['line_count'] ?></td><td><?= number_format((float)$r['total_qty'],3,',','.') ?></td><td><?= V::escape($r['status']) ?><?= $r['status']==='RESERVED'?' (Dalam Reservasi)':'' ?></td><td><a href="<?= $this->url('/inventory/reservation-detail?id='.(int)$r['id']) ?>">Detail</a></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="7" class="empty-state">Belum ada reservasi stok.</td></tr><?php endif ?></tbody></table></div></section>
